        foreach ($profiles as [$pattern, $category, $title, $summary, $steps, $fields]) {
            if (preg_match($pattern, $message) === 1) {
                return $this->profile($category, $title, $summary, $steps, $fields);
            }
        }

        return $this->profile('review', 'Retorno fiscal exige conferência',
            'A SEFAZ informou uma condição que precisa ser revisada antes de prosseguir.',
            ['Confira o motivo original e o campo ou grupo informado nos detalhes.', 'Encaminhe o código e o retorno ao responsável fiscal ou ao suporte. Se houve transmissão sem confirmação, consulte a mesma chave antes de outra tentativa.'],
            ['Campo ou grupo indicado no retorno SEFAZ']);
    }

    private function specific(?string $code, string $officialMessage): ?array
    {
        // NT 2024.001 changed 301/302/303 from denials to rejections. Historical
        // evidence must retain its meaning; numeric status alone is insufficient.
        if (in_array($code, ['301', '302', '303'], true)
            && preg_match('/denegad/iu', $officialMessage) !== 1) {
            return $this->profile('registration', 'Situação cadastral precisa de regularização',
                'A SEFAZ rejeitou a operação por uma irregularidade fiscal da pessoa indicada.',
                ['Confira no motivo original se a restrição se refere ao emitente ou ao destinatário e consulte o cadastro na SEFAZ.', 'Peça ao responsável fiscal que regularize a situação e confira o estado da nota antes de outra tentativa. Não altere o enquadramento ou a numeração para contornar a restrição.'],
                ['Situação cadastral do emitente ou destinatário']);
        }

        return match ($code) {
            '100', '120', '150' => $this->profile('authorization', 'Retorno de autorização recebido',
                'O serviço informou autorização; a confirmação no sistema depende da conferência do protocolo e do XML.',
                ['Confira a situação da nota e os arquivos preservados.', 'Se a nota continuar pendente, consulte a mesma chave para recuperar o protocolo. Preserve a numeração existente.'],
                ['Situação, protocolo e XML da nota']),
